// Simulador de erros: gera sismos com valores impossiveis (para testar a validacao no KNIME)
const agora = Date.now();
const mk = (id, mag, lon, lat, prof) => JSON.stringify({
  type: "Feature",
  properties: { mag: mag, place: "1 km N of Simulacao, Portugal", time: agora },
  geometry: { type: "Point", coordinates: [lon, lat, prof] },
  id: id
});
const casos = [
  ["SIM-MAG20-" + agora,      20,   -9.1, 38.7, 10],
  ["SIM-MAGNEG100-" + agora, -100,  -9.2, 38.8, 10],
  ["SIM-LAT123-" + agora,     4.5,  -9.3, 123,  10],
  ["SIM-PROF5000-" + agora,   3.0,  -9.4, 38.9, 5000]
];
const ids = casos.map(c => c[0]);
const payloads = casos.map(c => mk(c[0], c[1], c[2], c[3], c[4]));
msg.query = `INSERT INTO raw_sismos (fonte, formato, id_externo, payload)
SELECT 'USGS', 'geojson', t.id, t.p
FROM UNNEST($1::text[], $2::text[]) AS t(id, p)
ON CONFLICT (fonte, id_externo) DO NOTHING`;
msg.params = [ids, payloads];
return msg;
